package com.yeyamo_mobile.api.partner_service.infrastructure.staff;
import com.yeyamo_mobile.api.partner_service.application.port.*;import com.yeyamo_mobile.api.partner_service.infrastructure.persistence.*;import org.junit.jupiter.api.*;import org.springframework.data.redis.core.*;import java.util.*;import static org.assertj.core.api.Assertions.*;import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.*;
class PartnerStaffServiceTest{
 @Test void invitationStoresOnlyHashAndOwnerCannotBeRevoked(){SpringPartnerRepository partners=mock(SpringPartnerRepository.class);PartnerRoleRepository roles=mock(PartnerRoleRepository.class);PartnerMembershipRepository members=mock(PartnerMembershipRepository.class);PartnerInvitationRepository invites=mock(PartnerInvitationRepository.class);PartnerStaffAuditRepository audits=mock(PartnerStaffAuditRepository.class);PartnerOutboxPort outbox=mock(PartnerOutboxPort.class);StringRedisTemplate redis=mock(StringRedisTemplate.class);PartnerEntity partner=new PartnerEntity();UUID pid=UUID.randomUUID();partner.setId(pid);partner.setOwnerUserId("owner");when(partners.findById(pid)).thenReturn(Optional.of(partner));PartnerRoleEntity role=new PartnerRoleEntity();role.id=UUID.randomUUID();role.partnerId=pid;when(roles.findById(role.id)).thenReturn(Optional.of(role));when(invites.save(any())).thenAnswer(i->i.getArgument(0));when(audits.save(any())).thenAnswer(i->i.getArgument(0));PartnerStaffService service=new PartnerStaffService(partners,roles,members,invites,audits,outbox,redis);
  PartnerStaffService.InvitationResult result=service.invite(pid,"owner","User@Test.Com",role.id);var captor=org.mockito.ArgumentCaptor.forClass(PartnerInvitationEntity.class);verify(invites).save(captor.capture());assertThat(captor.getValue().tokenHash).doesNotContain(result.token());assertThat(captor.getValue().contact).isEqualTo("user@test.com");
  assertThatThrownBy(()->service.revoke(pid,"owner","owner")).isInstanceOf(IllegalStateException.class).hasMessageContaining("transfer");}
}
